<script module lang="ts">
/**
 * An Input preset for searching (`design/components/search-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/search-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import { agentFill, agentMember, joinSlot, watchEffect } from '@polymorph/svelte'
import styles from '@polymorph/recipes/controls/search-input.module.css'
import Input from './Input.svelte'
import Kbd from '../structure/Kbd.svelte'

export interface SearchInputProps {
  'aria-describedby'?: string
  /**
   * Required unless a FormField supplies a label. Search boxes rarely have visible labels.
   */
  'aria-label'?: string
  /**
   * Names the field from a label elsewhere on the page, such as `SettingsRow`'s row label, which
   * is one label for a whole row rather than one per control.
   */
  'aria-labelledby'?: string
  /**
   * The clear button's accessible name, passed to Input. Defaults to `Clear`.
   */
  clearLabel?: string
  defaultValue?: string
  disabled?: boolean
  id?: string
  name?: string
  onChange?: (value: string) => void
  placeholder?: string
  /**
   * A hint such as `⌘K`. Display only. Menu's `kbd` rule applies here too, and the vocabulary
   * never binds a global shortcut.
   */
  shortcut?: string
  size?: 'sm' | 'md' | 'lg'
  value?: string
}
</script>

<script lang="ts">
let {
  'aria-describedby': ariaDescribedbyOwn,
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledbyOwn,
  clearLabel,
  defaultValue,
  disabled = false,
  id: idOwn,
  name,
  onChange,
  placeholder = 'Search…',
  shortcut,
  size = 'md',
  value,
}: SearchInputProps = $props()
const joined = joinSlot(undefined, () => ({ disabled: disabled, name: name, size: size }))
const ariaDescribedby = $derived(
  joined.passed['aria-describedby'] === undefined
    ? ariaDescribedbyOwn
    : (joined.passed['aria-describedby'] as typeof ariaDescribedbyOwn),
)
const ariaLabelledby = $derived(
  joined.passed['aria-labelledby'] === undefined
    ? ariaLabelledbyOwn
    : (joined.passed['aria-labelledby'] as typeof ariaLabelledbyOwn),
)
const id = $derived(
  joined.passed['id'] === undefined ? idOwn : (joined.passed['id'] as typeof idOwn),
)
let focused = $state(false)
// svelte-ignore state_referenced_locally
let mirror = $state(defaultValue ?? '')
let frame = $state<HTMLElement | null>(null)
const current = $derived(value ?? mirror)
const showShortcut = $derived(shortcut !== undefined && current === '' && !focused && !disabled)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'SearchInput',
    element: () => frame?.querySelector('input'),
    state: () => ({ value: current, disabled: disabled }),
    actions: {
      fill: { argument: 'text', run: (value) => agentFill(frame?.querySelector('input'), value) },
      clear: () => agentFill(frame?.querySelector('input'), ''),
    },
    withholds: () => frame,
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<span
    bind:this={frame}
    class={styles.search}
    data-shortcut={(showShortcut) ? '' : undefined}
    data-member="search-input"
    onfocusin={() => { focused = true }}
    onfocusout={() => { focused = false }}
    >{#snippet trailingOfInput1()
      }<span class={styles.hint} aria-hidden="true"><Kbd>{shortcut}</Kbd></span
    >{/snippet
    }<Input
      type="search"
      icon="search"
      clearable={true}
      {clearLabel}
      {size}
      {disabled}
      {value}
      {defaultValue}
      {placeholder}
      aria-label={ariaLabel}
      aria-labelledby={ariaLabelledby}
      aria-describedby={ariaDescribedby}
      {id}
      {name}
      onChange={(event) => { (mirror = event, onChange?.(event)) }}
      trailing={showShortcut ? trailingOfInput1 : undefined}
  /></span
>{/if
}{@render joined.end?.()}
